function parseCsv(text){
  var rows=[]; var row=[]; var field=''; var i=0; var inQ=false;
  text=text.replace(/\r\n/g,'\n').replace(/\r/g,'\n');
  while(i<text.length){
    var c=text[i];
    if(inQ){
      if(c==='"'){ if(text[i+1]==='"'){ field+='"'; i+=2; continue; } inQ=false; i++; continue; }
      field+=c; i++; continue;
    } else {
      if(c==='"'){ inQ=true; i++; continue; }
      if(c===','){ row.push(field); field=''; i++; continue; }
      if(c==='\n'){ row.push(field); rows.push(row); row=[]; field=''; i++; continue; }
      field+=c; i++;
    }
  }
  if(field.length>0 || row.length>0) { row.push(field); rows.push(row); }
  return rows;
}
function csvToJson(text){
  var rows=parseCsv(text).filter(function(r){return r.length>1||r[0]!=='';});
  if(!rows.length) return [];
  var header=rows[0]; var out=[];
  for(var k=1;k<rows.length;k++){ var obj={}; for(var j=0;j<header.length;j++) obj[header[j]]=rows[k][j]!==undefined?rows[k][j]:''; out.push(obj); }
  return out;
}
function csvEscape(s){ if(/[",\n]/.test(s)) return '"'+String(s).replace(/"/g,'""')+'"'; return s; }
function jsonToCsv(arr){
  if(!arr.length) return '';
  var header=Object.keys(arr[0]);
  var lines=[header.join(',')];
  for(var k=0;k<arr.length;k++){ var row=header.map(function(h){return csvEscape(arr[k][h]);}); lines.push(row.join(',')); }
  return lines.join('\n');
}
var EXPORTS={csvToJson:csvToJson, jsonToCsv:jsonToCsv, parseCsv:parseCsv};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CsvToJsonForgePure = EXPORTS; }
